scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode) {
        return;
    }
    var hits = new global.EcsPortability(new global.EcsAst(engine.rootNode)).instanceUrls();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-CFG-001-R',
        title: 'Hardcoded ServiceNow instance host',
        recommendation: 'Build instance URLs at run time with gs.getProperty(\'glide.servlet.uri\') (this ' +
            'instance) or gs.getProperty(\'instance_name\'). For other instances or endpoints, use a Connection & ' +
            'Credential alias, a REST Message endpoint, or a system property set per environment.'
    });
    for (var i = 0; i < hits.length; i++) {
        if (hits[i].tier === 'other') {
            report.add(hits[i].node, hits[i].message);
        }
    }
    report.flush();
})(engine);
